// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        // Keep amount strictly between 0 and 10 ether to avoid overflow and keep execution cheap,
        // but exactly MinDeposit (1 ether) is the interesting boundary.
        vm.assume(amount > 0 && amount <= 10 ether);

        // Remember balance before deposit
        uint256 balanceBefore = c.balances(actor);

        vm.deal(actor, amount);
        vm.prank(actor);
        try c.Deposit{value: amount}() {} catch {}

        uint256 balanceAfter = c.balances(actor);

        // Universal rule: if msg.value == MinDeposit, balance MUST NOT change.
        // The reference ignores ==, the bug accepts >=, so the bug breaks this for amount == MinDeposit.
        bool invariantHolds = (amount != c.MinDeposit()) || (balanceAfter == balanceBefore);
        assertTrue(invariantHolds);
    }
}

