pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint112 amt1, uint112 amt2) public {
        // sender must be a valid address, not zero
        vm.assume(sender != address(0));
        // Avoid the contract itself as sender to keep accounting simple
        vm.assume(sender != address(c));
        // amt1 and amt2 are uint112, so they fit, but adding them may overflow uint112 balances if allowed.
        // We need two deposits: first deposit amt1, second deposit amt2.
        // Both must be > MinDeposit to be accepted.
        vm.assume(amt1 > c.MinDeposit());
        vm.assume(amt2 > c.MinDeposit());

        // Fund sender with enough Ether for both deposits
        uint256 totalFund = uint256(amt1) + uint256(amt2);
        vm.deal(sender, totalFund);

        // First deposit
        vm.prank(sender);
        c.Deposit{value: uint256(amt1)}();

        // Record sum of balances after first deposit
        uint256 sumAfterFirst = 0;
        sumAfterFirst += c.balances(sender);

        // Second deposit
        vm.prank(sender);
        c.Deposit{value: uint256(amt2)}();

        // Record sum of balances after second deposit
        uint256 sumAfterSecond = c.balances(sender);

        // In the correct contract, sumAfterSecond should be equal to sumAfterFirst + amt2,
        // because the overflow check prevents wrapping.
        // In the buggy one, an overflow could make sumAfterSecond < sumAfterFirst + amt2,
        // breaking the invariant that total tracked balance equals total deposited amount.
        assertTrue(sumAfterSecond == sumAfterFirst + uint256(amt2));
    }
}

