pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 deposit1, uint256 deposit2) public {
        // Use only one address to isolate the accumulation bug
        address alice = address(0x1000);
        uint256 minDep = c.MinDeposit();
        vm.assume(deposit1 > minDep);
        vm.assume(deposit2 > minDep);
        vm.assume(deposit1 <= 1000 ether);
        vm.assume(deposit2 <= 1000 ether);
        vm.assume(uint256(deposit1) + uint256(deposit2) < type(uint256).max);
        vm.deal(alice, deposit1 + deposit2);

        // First deposit
        vm.prank(alice);
        c.Deposit{value: deposit1}();
        uint256 balAfterFirst = c.balances(alice);

        // Second deposit
        vm.prank(alice);
        c.Deposit{value: deposit2}();
        uint256 balAfterSecond = c.balances(alice);

        // For the reference C, the balance after two deposits must equal the sum of both.
        // The buggy version sets balances[msg.sender] = msg.value on each call, so after
        // the second deposit, balAfterSecond == deposit2, which breaks the sum rule.
        assertTrue(balAfterSecond == deposit1 + deposit2);
    }
}

