import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amt, address caller, address other) public {
        // keep amt within reasonable bounds but allow overflow
        vm.assume(amt > 1 ether);
        vm.assume(amt < type(uint256).max - 1000 ether);
        vm.assume(caller != other);
        vm.assume(caller != address(0));
        vm.assume(other != address(0));

        // record balances before any deposit
        uint256 callerBalBefore = c.balances(caller);
        uint256 otherBalBefore = c.balances(other);

        // amt > MinDeposit so Deposit logic runs; it will overflow because callerBalBefore + amt < amt only if callerBalBefore is huge
        // but we want a revert; we need callerBalBefore such that callerBalBefore + amt < callerBalBefore
        // so we deal caller some balance if needed, but we want an overflow. The fuzzer can pick caller with existing balance.
        // we don't control callerBalBefore directly, so we make a successful deposit first to set it high.
        vm.deal(address(this), 1 ether);
        c.Deposit{value: 1 ether}();
        if (callerBalBefore > 0) {
            // just ensure caller has enough ether to send
        }
        // To guarantee overflow revert: we need balances[caller] + amt < balances[caller].
        // We can set balances[caller] high by doing a legit deposit from caller.
        // First we need ether on caller.
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.Deposit{value: 1 ether}();
        // Now balances[caller] = 1 ether.
        // We need amt such that 1 ether + amt overflows? No, we want balances[caller] + amt < balances[caller] which requires balances[caller] > type(uint256).max - amt.
        // The fuzzer picks amt, so we artificially raise caller balance to near max.
        // We can do multiple deposits? Not easily without hardcoding. Instead, we rely on the fuzzer picking amt that will cause overflow with whatever balance caller has.
        // But caller might have 0 balance; then no overflow. So we force caller to have a large balance by using a helper? No, we must let fuzzer explore.
        // However, we want the test to PASS on reference for ALL inputs and FAIL on buggy for SOME input.
        // If caller balance is low, amt might not overflow, so both pass. That's fine; we need existence of a failing case.
        // For buggy: even if amt does not overflow, the require check might pass; then balances updated normally. No difference.
        // The difference only occurs when require reverts. So we need a revert case. The fuzzer will eventually explore amt large enough to overflow with the current balance.
        // But note: the reference always reverts if overflow, keeping balances unchanged. Buggy increments before check, so balance increases wrongly.
        // Our property: after any Deposit, for any other address, its balance must equal its balance after the last successful deposit by that other address, provided that other address hasn't deposited successfully in between.
        // Actually simpler: for any address X, a call to Deposit from caller should never increase X's balance unless the deposit succeeds and X is the caller.
        // But the bug increases caller's balance even on revert. So: after Deposit from caller, if the call reverts (we detect via try/catch), the caller's balance must equal its pre-balance. For other address, arbitrary.
        // But the fuzzer must detect revert. Use try/catch with low-level call? Can't call Deposit externally via try/catch because it's not external? Deposit is public, so yes.
        // We'll call c.Deposit with value from caller, catch revert, check balance.
        vm.deal(caller, amt); // may be huge
        bool ok;
        vm.prank(caller);
        try c.Deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference satisfies: if !ok (Deposit reverted), then caller balance must equal callerBalBefore.
        // Buggy violates: if !ok, caller balance could be different (higher) because they incremented before check.
        assertTrue(!ok ? c.balances(caller) == callerBalBefore : true);
    }
}

